# find thirteen adjacent digits that have greatest product

import math
import operator
from functools import reduce 

# convert to list so don't need to do this arithmetic every time
def toList(x: int) -> list[int]:
    y = []
    for i in reversed(range(int(math.log10(x))+1)):
        y.append((x // 10**i) % 10)
    return y

y = toList(x)
max_value = 0
max_index = None
for i in range(len(y)-13):
    value = reduce(operator.mul,y[i:i+13], 1)
    if value > max_value:
        max_value = value
        max_index = i
print(max_value)
print(max_index)
print(y[max_index:max_index+13])